SECTIONS = ["overview", "ontology", "agents", "facts", "signals", "rules", "actions", "watch_rules", "kpis"]


def slug(s: str, upper=False) -> str:
    v = re.sub(r"[^A-Za-z0-9]+", "_", str(s or "")).strip("_")
    return v.upper() if upper else v.lower()


def normalise(c: dict) -> dict:
    """Tidy model output into canonical shapes (ids, defaults). Never invents meaning."""
    c = dict(c or {})
    for k in ("ontology", "facts", "signals", "rules", "actions", "agents", "kpis", "starter_questions", "primary_users", "watch_rules"):
        c[k] = [x for x in (c.get(k) or []) if x]
    for f in c["facts"]:
        f["name"] = slug(f.get("name"))
        f["type"] = f.get("type") if f.get("type") in FACT_TYPES else "string"
    for s in c["signals"]:
        s["id"] = slug(s.get("id"))
        s["combine"] = s.get("combine") if s.get("combine") in ("weighted_sum", "noisy_or") else "weighted_sum"
        for i in s.get("inputs") or []:
            i["fact"] = slug(i.get("fact"))
    for a in c["actions"]:
        a["name"] = slug(a.get("name"), upper=True)
        a["risk"] = (a.get("risk") or "HIGH").upper()
        a["required_facts"] = [slug(x) for x in a.get("required_facts") or []]
        a["amount_fact"] = slug(a["amount_fact"]) if a.get("amount_fact") else None
        a.setdefault("always_review", False)
        a.setdefault("auto_approve_below", None)
        a["owner_role"] = (a.get("owner_role") or "Reviewer").strip()
        ex = a.get("executor") if isinstance(a.get("executor"), dict) else {}
        if ex.get("type") == "database":
            a["executor"] = {"type": "database", "connection_id": ex.get("connection_id"), "table": ex.get("table"),
                             "operation": ex.get("operation") if ex.get("operation") in ("insert", "update") else "update",
                             "key_column": ex.get("key_column"), "columns": [str(x) for x in ex.get("columns") or []]}
        else:  # webhook (also migrates the older top-level webhook_url field)
            a["executor"] = {"type": "webhook", "url": ex.get("url") or a.get("webhook_url") or ""}
        a.pop("webhook_url", None)
    for w in c["watch_rules"]:
        w["id"] = slug(w.get("id") or w.get("event_type"))
        w["event_type"] = str(w.get("event_type") or "").strip()
        w["owner_role"] = (w.get("owner_role") or "").strip()
    for r in c["rules"]:
        r["id"] = slug(r.get("id"))
        r["applies_to"] = ["*" if x == "*" else slug(x, upper=True) for x in (r.get("applies_to") or ["*"])]
        r["on_fail"] = r.get("on_fail") if r.get("on_fail") in ("INVALID", "INSUFFICIENT_EVIDENCE") else "INVALID"
        r["condition"] = _norm_cond(r.get("condition"))
    for g in c["agents"]:
        g["id"] = slug(g.get("id") or g.get("name"))
        g["tools"] = [t for t in g.get("tools") or [] if t in TOOLS]
        g["actions"] = [slug(x, upper=True) for x in g.get("actions") or []]
        g["data_scope"] = [d for d in g.get("data_scope") or [] if isinstance(d, dict)]
    return c


def _norm_cond(cond):
    if not isinstance(cond, dict):
        return cond
    if "all" in cond or "any" in cond:
        k = "all" if "all" in cond else "any"
        return {k: [_norm_cond(x) for x in cond[k] or []]}
    if "not" in cond:
        return {"not": _norm_cond(cond["not"])}
    c = dict(cond)
    if "fact" in c and "path" not in c:
        c["path"] = c.pop("fact")
    if "path" in c:
        p = str(c["path"])
        c["path"] = ("signals." + slug(p.split(".", 1)[1])) if p.startswith("signals.") else slug(p.replace("facts.", ""))
    if isinstance(c.get("value"), str) and c["value"].startswith("$"):
        c["value"] = "$" + slug(c["value"][1:])
    return c


def _paths(cond):
    if not isinstance(cond, dict):
        return []
    if "all" in cond or "any" in cond:
        return [p for x in cond.get("all", cond.get("any")) or [] for p in _paths(x)]
    if "not" in cond:
        return _paths(cond["not"])
    out = [cond["path"]] if "path" in cond else []
    if isinstance(cond.get("value"), str) and cond["value"].startswith("$"):
        out.append(cond["value"][1:])
    return out


def validate(c: dict, connections: dict, roles: set | None = None) -> dict:
    """Symbolic validation. connections: {id: {"tables": {table: [columns]}, "endpoints": [...], "allow_writes": bool}}
    roles: the organisation's role names (owner roles must exist)."""
    errors, warnings = [], []
    facts = {f["name"]: f for f in c.get("facts", [])}
    signals = {s["id"] for s in c.get("signals", [])}
    actions = {a["name"]: a for a in c.get("actions", [])}

    def dup(items, key, what):
        seen = set()
        for x in items:
            if x.get(key) in seen:
                errors.append(f"Duplicate {what} '{x.get(key)}'")
            seen.add(x.get(key))
    dup(c.get("facts", []), "name", "fact")
    dup(c.get("signals", []), "id", "signal")
    dup(c.get("rules", []), "id", "rule")
    dup(c.get("actions", []), "name", "action")
    dup(c.get("agents", []), "id", "agent")

    if not c.get("summary"):
        errors.append("Overview: a product summary is required")
    for o in c.get("ontology", []):
        src = o.get("source") or {}
        if src.get("connection_id"):
            con = connections.get(src["connection_id"])
            if not con:
                errors.append(f"Ontology '{o['name']}': connection '{src['connection_id']}' does not exist")
            elif src.get("table") and src["table"] not in con["tables"]:
                errors.append(f"Ontology '{o['name']}': table '{src['table']}' does not exist in that connection")
    for s in c.get("signals", []):
        if not s.get("inputs"):
            errors.append(f"Signal '{s['id']}': needs at least one input")
        for i in s.get("inputs", []):
            f = facts.get(i.get("fact"))
            if not f:
                errors.append(f"Signal '{s['id']}': fact '{i.get('fact')}' is not defined")
            elif f["type"] == "string":
                errors.append(f"Signal '{s['id']}': fact '{f['name']}' is text; soft signals need numbers or booleans")
        try:
            if not (0 <= float(s["deny_below"]) <= float(s["assert_above"]) <= 1):
                errors.append(f"Signal '{s['id']}': thresholds must satisfy 0 ≤ deny_below ≤ assert_above ≤ 1")
        except (KeyError, TypeError, ValueError):
            errors.append(f"Signal '{s['id']}': thresholds must be numbers")
        if s.get("combine") == "noisy_or" and any(not (0 <= float(i.get("weight", 1)) <= 1) for i in s.get("inputs", [])):
            errors.append(f"Signal '{s['id']}': noisy_or weights are strengths and must be between 0 and 1")
    for r in c.get("rules", []):
        cond_errs = []
        expr.validate_condition(r.get("condition"), f"Rule '{r['id']}'", cond_errs)
        errors += cond_errs
        if not r.get("condition"):
            errors.append(f"Rule '{r['id']}': a condition is required")
        for p in _paths(r.get("condition")):
            if p.startswith("signals."):
                if p.split(".", 1)[1] not in signals:
                    errors.append(f"Rule '{r['id']}': signal '{p}' is not defined")
            elif p not in facts:
                errors.append(f"Rule '{r['id']}': fact '{p}' is not defined")
        for a in r.get("applies_to", []):
            if a != "*" and a not in actions:
                errors.append(f"Rule '{r['id']}': applies to unknown action '{a}'")
        if not r.get("citation"):
            warnings.append(f"Rule '{r['id']}' has no citation, add the document and page it comes from")
    for a in actions.values():
        if a["risk"] not in RISKS:
            errors.append(f"Action '{a['name']}': risk must be one of {RISKS}")
        for f in a.get("required_facts", []):
            if f not in facts:
                errors.append(f"Action '{a['name']}': required fact '{f}' is not defined")
        if a.get("amount_fact") and a["amount_fact"] not in facts:
            errors.append(f"Action '{a['name']}': amount fact '{a['amount_fact']}' is not defined")
        if a["risk"] != "LOW" and not any(a["name"] in r.get("applies_to", []) or "*" in r.get("applies_to", []) for r in c.get("rules", [])):
            warnings.append(f"Action '{a['name']}' is {a['risk']} risk but no rule checks it, every such request will go to a human")
        ex = a.get("executor") or {}
        if ex.get("type") == "webhook":
            if ex.get("url") and not re.match(r"^https?://", ex["url"]):
                errors.append(f"Action '{a['name']}': webhook URL must start with http:// or https://")
            if not ex.get("url"):
                warnings.append(f"Action '{a['name']}' has no webhook URL yet, approved requests will be recorded but not sent")
        elif ex.get("type") == "database":
            con = connections.get(ex.get("connection_id"))
            cols = (con or {}).get("tables", {}).get(ex.get("table"))
            if not con:
                errors.append(f"Action '{a['name']}': data connection '{ex.get('connection_id')}' does not exist")
            elif cols is None:
                errors.append(f"Action '{a['name']}': table '{ex.get('table')}' does not exist in that connection")
            else:
                if not ex.get("columns"):
                    errors.append(f"Action '{a['name']}': list the columns this action may write")
                for col in ex.get("columns") or []:
                    if col not in cols:
                        errors.append(f"Action '{a['name']}': column '{col}' does not exist in '{ex['table']}'")
                if ex.get("operation") == "update" and ex.get("key_column") not in cols:
                    errors.append(f"Action '{a['name']}': an update needs a key column that exists in '{ex['table']}'")
                if not con.get("allow_writes"):
                    warnings.append(f"Action '{a['name']}' writes to '{ex['table']}', but writes are not enabled on that connection, an admin must enable them")
        if roles is not None and a.get("owner_role") not in roles:
            warnings.append(f"Action '{a['name']}': owner role '{a.get('owner_role')}' does not exist, create it in Roles & access or choose another")
    for w in c.get("watch_rules", []):
        if not w.get("event_type"):
            errors.append(f"Watch rule '{w.get('id')}': event_type is required")
        if w.get("when"):
            cond_errs = []
            expr.validate_condition(w["when"], f"Watch rule '{w['id']}'", cond_errs)
            errors += cond_errs
        if roles is not None and w.get("owner_role") and w["owner_role"] not in roles:
            warnings.append(f"Watch rule '{w['id']}': owner role '{w['owner_role']}' does not exist")
    if not c.get("agents"):
        errors.append("Agent team: at least one specialist agent is required")
    for g in c.get("agents", []):
        if not g.get("tools"):
            errors.append(f"Agent '{g['id']}': needs at least one tool")
        for act in g.get("actions", []):
            if act not in actions:
                errors.append(f"Agent '{g['id']}': action '{act}' is not defined")
        for d in g.get("data_scope", []):
            con = connections.get(d.get("connection_id"))
            if not con:
                errors.append(f"Agent '{g['id']}': data connection '{d.get('connection_id')}' does not exist")
                continue
            for t in d.get("tables") or []:
                if t != "*" and t not in con["tables"]:
                    errors.append(f"Agent '{g['id']}': table '{t}' does not exist in connection '{d['connection_id']}'")
        if ("query_data" in g.get("tools", []) or "call_api" in g.get("tools", [])) and not g.get("data_scope"):
            warnings.append(f"Agent '{g['id']}' can query data but has no data scope")
    return {"errors": errors, "warnings": warnings, "ok": not errors}


def engine_rules(c: dict, action: str) -> dict:
    """Compile the blueprint into the rule engine's declarative form for one action."""
    ftype = {"number": "number", "boolean": "bool", "string": "string"}
    return {
        # Stage 1 output: each fact's value, and the extraction confidence the agent reported for it (if any).
        "features": {f["name"]: {"from": f"facts.{f['name']}", "type": ftype[f["type"]], "description": f.get("description", ""),
                                 "confidence_from": f"evidence.{f['name']}.confidence"}
                     for f in c.get("facts", [])},
        "soft": [{"id": s["id"], "version": "1", "output": s["id"], "description": s.get("description", ""), "combine": s.get("combine", "weighted_sum"),
                  "inputs": [{k: v for k, v in i.items() if k in ("weight", "invert", "min", "max")} | {"feature": i["fact"]} for i in s["inputs"]]}
                 for s in c.get("signals", [])],
        "thresholds": [{"signal": s["id"], "from": s["id"], "assert_above": float(s["assert_above"]), "deny_below": float(s["deny_below"]),
                        "min_coverage": 0.6, "version": "1"} for s in c.get("signals", [])],
        "hard": [{"id": r["id"], "version": "1", "description": r.get("description", ""), "citation": r.get("citation"),
                  "require": r["condition"], "on_fail": r.get("on_fail", "INVALID"), "message": r.get("message") or r.get("description")}
                 for r in c.get("rules", []) if "*" in r.get("applies_to", []) or action in r.get("applies_to", [])],
    }


# ======================================================================== business rules as YAML
# The business rules are the parts of a blueprint a business edits most: the fact vocabulary, soft signals, hard
# rules, actions (risk, owner, executor) and Aria Watch's watch rules. They can be downloaded and uploaded as YAML.
RULE_SECTIONS = ["facts", "signals", "rules", "actions", "watch_rules"]
KEY = {"facts": "name", "signals": "id", "rules": "id", "actions": "name", "watch_rules": "id", "agents": "id", "ontology": "name", "kpis": "name"}
REQUIRED = {"facts": ["name", "type"], "signals": ["id", "inputs", "assert_above", "deny_below"], "rules": ["id", "condition"],
            "actions": ["name", "risk"], "watch_rules": ["id", "event_type"]}
META = {"version", "name", "description", "organisation", "updated", "notes"}
LABEL = {"facts": "Fact", "signals": "Signal", "rules": "Rule", "actions": "Action", "watch_rules": "Watch rule",
         "agents": "Agent", "ontology": "Entity", "kpis": "KPI"}


def rules_yaml(content: dict, version: int) -> str:
    import yaml
    doc = {"version": version, "description": "Aria XAI business rules. Edit and upload to propose a new version."}
    for s in RULE_SECTIONS:
        doc[s] = content.get(s) or []
    return yaml.safe_dump(doc, sort_keys=False, allow_unicode=True, width=120)


def parse_rules_yaml(text: str) -> tuple[dict, list[str]]:
    """Return (sections, errors). A file that is not YAML, or does not look like Aria XAI business rules, is an error."""
    import yaml
    if not (text or "").strip():
        return {}, ["The file is empty."]
    if len(text) > 2_000_000:
        return {}, ["The file is too large (over 2 MB) to be a business-rules file."]
    try:
        doc = yaml.safe_load(text)
    except yaml.YAMLError as ex:
        mark = getattr(ex, "problem_mark", None)
        where = f" (line {mark.line + 1}, column {mark.column + 1})" if mark else ""
        return {}, [f"This is not valid YAML{where}: {getattr(ex, 'problem', None) or ex}."]
    if not isinstance(doc, dict):
        return {}, ["This file does not contain Aria XAI business rules. Expected a YAML mapping with sections such as "
                    "facts, rules, signals, actions and watch_rules."]
    unknown = sorted(str(k) for k in doc if k not in RULE_SECTIONS and k not in META)
    present = [s for s in RULE_SECTIONS if s in doc]
    if not present:
        return {}, ["This file does not contain Aria XAI business rules: none of the sections facts, signals, rules, actions "
                    "or watch_rules were found." + (f" It has: {', '.join(unknown[:8])}." if unknown else "")]
    errors = [f"Unknown section '{k}'. Allowed sections: {', '.join(RULE_SECTIONS)}." for k in unknown]
    out = {}
    for s in present:
        items = doc[s]
        if items is None:
            items = []
        if not isinstance(items, list):
            errors.append(f"'{s}' must be a list of entries.")
            continue
        seen = set()
        for i, it in enumerate(items, 1):
            if not isinstance(it, dict):
                errors.append(f"{LABEL[s]} #{i} in '{s}' must be a mapping of fields, not {type(it).__name__}.")
                continue
            missing = [f for f in REQUIRED[s] if it.get(f) in (None, "", [])]
            if missing:
                errors.append(f"{LABEL[s]} #{i} in '{s}' is missing: {', '.join(missing)}.")
            k = it.get(KEY[s])
            if k in seen:
                errors.append(f"{LABEL[s]} '{k}' appears more than once.")
            seen.add(k)
        out[s] = items
    return out, errors


def _brief(v) -> str:
    import json
    s = v if isinstance(v, str) else json.dumps(v, default=str)
    return s if len(s) <= 160 else s[:157] + "..."


def diff(old: dict, new: dict, sections: list[str] | None = None) -> list[dict]:
    """Field-level differences between two blueprint contents, keyed by each entry's id or name."""
    out = []
    for s in sections or [*RULE_SECTIONS, "agents", "ontology", "kpis"]:
        k = KEY[s]
        a = {x.get(k): x for x in old.get(s) or [] if isinstance(x, dict)}
        b = {x.get(k): x for x in new.get(s) or [] if isinstance(x, dict)}
        for key in b.keys() - a.keys():
            out.append({"section": s, "label": LABEL[s], "id": key, "change": "added", "fields": []})
        for key in a.keys() - b.keys():
            out.append({"section": s, "label": LABEL[s], "id": key, "change": "removed", "fields": []})
        for key in a.keys() & b.keys():
            fields = [{"field": f, "before": _brief(a[key].get(f)), "after": _brief(b[key].get(f))}
                      for f in sorted(set(a[key]) | set(b[key])) if a[key].get(f) != b[key].get(f)]
            if fields:
                out.append({"section": s, "label": LABEL[s], "id": key, "change": "changed", "fields": fields})
    if sections is None:
        for f in ("summary", "industry", "business_model"):
            if old.get(f) != new.get(f):
                out.append({"section": "overview", "label": "Overview", "id": f, "change": "changed",
                            "fields": [{"field": f, "before": _brief(old.get(f)), "after": _brief(new.get(f))}]})
    order = {"added": 0, "changed": 1, "removed": 2}
    return sorted(out, key=lambda c: (RULE_SECTIONS.index(c["section"]) if c["section"] in RULE_SECTIONS else 9, order[c["change"]], str(c["id"])))
